mapper.select:
SELECT series_id,campaign_id,campaign_version,COUNT(*) orders,SUM(paid) paid_orders,
CAST(SUM(IF(paid,paid_amount,0)) AS CHAR) received,CAST(SUM(IF(paid,refunded,0)) AS CHAR) refunded,
CAST(SUM(IF(paid,paid_amount-refunded,0)) AS CHAR) net_receipts,CAST(SUM(IF(paid,discount_amount,0)) AS CHAR) discount_granted,
CAST(SUM(IF(paid,platform_funding,0)) AS CHAR) platform_funding,CAST(SUM(IF(paid,merchant_funding,0)) AS CHAR) merchant_funding,MAX(updated_at) updated_at
FROM marketing_effect_order WHERE tenant_id=#{tenant} AND store_id=#{store} AND ordered_at>=#{from} AND ordered_at<#{to} AND series_id>#{after}
GROUP BY series_id,campaign_id,campaign_version ORDER BY series_id LIMIT #{limit}
